function frontAtY(y) {
  return bodyAtXY(0,y,true);
}

function bodyAtXY(x,y,front=true) {
  const sourceX=sleeveSourceX(x,y);
  let lo=0,hi=1;
  for(let n=0;n<22;n++){
    const t=(lo+hi)/2,p=profile(t),a=Math.asin(clamp(sourceX/p[0],-1,1));
