function bodyNormal(x,y) {
  const e=.0008,zx=(bodyAtXY(x+e,y)[2]-bodyAtXY(x-e,y)[2])/(2*e);
  const zy=(bodyAtXY(x,y+e)[2]-bodyAtXY(x,y-e)[2])/(2*e);
  return new THREE.Vector3(-zx,-zy,1).normalize();
}

function contactBroadening(x){
