}

function collarLeafOcclusion(side,u,v){
  const h=collarLeafBend(side,u,v),e=.07;
  const l=collarLeafBend(side,Math.max(0,u-e),v),r=collarLeafBend(side,Math.min(1,u+e),v);
  return clamp(Math.max(0,(l+r)*.5-h)*4.5,0,.085);
