function facingPoint(side,u,v){
  const upperTurn=1-smooth(0,.25,v),edge=torsoPoint(side*(1-v)*.25,0);
  const x=edge[0]+side*u*(.062+.010*v-.012*upperTurn)+placketX(.780)*Math.pow(v,4);
