      [m[k],m[pivot]]=[m[pivot],m[k]];const d=m[k][k];minimumPivot=Math.min(minimumPivot,Math.abs(d));
      if(Math.abs(d)<1e-10)throw new Error('Ill-conditioned147 field.');
