      if(!Number.isFinite(p.getX(i))||!Number.isFinite(p.getY(i))||!Number.isFinite(p.getZ(i))
        ||!Number.isFinite(n.getX(i))||!Number.isFinite(n.getY(i))||!Number.isFinite(n.getZ(i)))
