 for(let c=0;c<3;c++)mean[c]/=weightSum;
 const pixels=new Uint8Array(N*N*4);let minGain=1,maxGain=1,changed=0,gainSum=0,clippedChannels=0,maxUnclippedColor=0;
 for(let i=0;i<N*N;i++){
  const at=i*4,mask=field[at+3];let altered=false;
  for(let c=0;c<3;c++){
   const gain=mask?1+strength*mask*.22*Math.tanh(Math.log(field[at+c]/mean[c])/.22):1;
   if(!Number.isFinite(gain))throw new Error('Nonfinite cloth117 gain.');
   minGain=Math.min(minGain,gain);maxGain=Math.max(maxGain,gain);if(mask)gainSum+=gain;
   const raw=baseColor[c]*gain;if(raw>1)clippedChannels++;maxUnclippedColor=Math.max(maxUnclippedColor,raw);
   const value=Math.round(encoded(clamp(raw)));pixels[at+c]=value;altered ||= value!==neutral[c];
  }
  pixels[at+3]=255;if(altered)changed++;
 }
 const map=new THREE.DataTexture(pixels,N,N,THREE.RGBAFormat);map.colorSpace=THREE.SRGBColorSpace;
 map.wrapS=THREE.RepeatWrapping;map.wrapT=THREE.ClampToEdgeWrapping;map.generateMipmaps=true;map.minFilter=THREE.LinearMipmapLinearFilter;map.magFilter=THREE.LinearFilter;map.anisotropy=8;map.needsUpdate=true;
 map.name='Image1 manually registered cotton-panel shading117';
 // Store complete bounded base color in the map. Raising an almost-white
 // material factor above one to create texture headroom would violate glTF's
 // baseColorFactor range. Only the small photographic bright tail can clip.
 const material=original.clone();material.map=map;material.color.setRGB(1,1,1);material.needsUpdate=true;
 const metrics=Object.freeze({iteration:117,strength,applied:true,source:'Only user-supplied image1; two manual cotton interiors, photographic shading not measured albedo',sourceSamples,minimumSourceRGB,normalizationRGB:mean,changedAtlasTexels:changed,minGain,maxGain,meanSampleGain:gainSum/(3*sourceSamples),baseColorBaked:baseColor,clippedChannels,maxUnclippedColor,neutralLinearQuantizationMax:Math.max(...baseColor.map((c,i)=>Math.abs(c-linear(neutral[i]/255)))),atlas:[N,N],additionalCPUTextureMiB:4,estimatedGPUMipMiB:16/3,temporaryFieldMiB:16,geometryChanged:false,uvChanged:false,elapsedMs:performance.now()-started});
 torso.material=material;applications.set(blouse,{strength,metrics,torso,original,material,map});
 return metrics;
}

export function releaseReferenceCloth117(blouse){
 const saved=applications.get(blouse);if(!saved)return false;
 if(saved.torso.material!==saved.material)throw new Error('Cloth117 material changed before release.');
 saved.torso.material=saved.original;saved.material.dispose();saved.map.dispose();applications.delete(blouse);return true;
}

