    const [a, b, c] = ps;
    const wa = ((b[1] - c[1]) * (x - c[0]) + (c[0] - b[0]) * (y - c[1])) / determinant;
    const wb = ((c[1] - a[1]) * (x - c[0]) + (a[0] - c[0]) * (y - c[1])) / determinant;
    return wa * a[2] + wb * b[2] + (1 - wa - wb) * c[2];
  };
